import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a sword → base premium 100 G (+10 G first insurance +5 G fee = 115 G)");
    it.todo("an amulet → base premium 60 G");
    it.todo("a staff → base premium 80 G");
    it.todo("a potion → base premium 40 G");
    it.todo("a single rune → base premium 25 G");
    it.todo("a single moonstone → base premium 25 G");
  });

  describe("quote — component blocks of 3 alike", () => {
    it.todo("2 runes → 50 G base premium (no block)");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium (no block for 7)");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — premium modifiers", () => {
    it.todo("cursed sword adds 50 % of its base premium (50 G surcharge)");
    it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge (30 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("first insurance adds 10 % initial assessment surcharge");
    it.todo("second contract in a scenario receives a 15 % follow-up discount");
    it.todo("a 5 G processing fee is added to every premium");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo(
      "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee",
    );
    it.todo("policy-wide modifiers apply to the sum of all item base premiums");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed sword (steel, ench. 3) → premium 165 G");
    it.todo(
      "3-year customer's second quote with a cursed sword (steel, ench. 7) → premium 160 G (first insurance still applies per item)",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G (no special clause)");
    it.todo("deductible applies once per damaged item: sword 500 G + amulet 300 G → payout 600 G");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("cursed sword (premium 165 G) → cap 2000 G, based on unmodified insurance value");
    it.todo("policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
    it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two sword damage entries against two insured swords → each treated as a separate damage with its own deductible");
    it.todo("more damage entries of a type than insured items (two sword damages, one sword) → error, claim rejected");
  });

  describe("errors", () => {
    it.todo("quote with an unknown item type (e.g. broomstick) → error");
    it.todo("claim referencing an item not part of the policy (amulet damaged, only sword insured) → error");
    it.todo("claim referencing a damage entry with an unknown item type → error");
    it.todo("claim containing a damage entry with amount -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes {results: [...]} to stdout in step order");
    it.todo("quote step result contains premium; claim step result contains payout and remainingCap");
    it.todo("on an invalid scenario exits with a non-zero status code and writes an error description to stderr, with no results on stdout");
  });
});

