const PROCESSING_FEE = 5;

export type Item = { type: string };
export type Step = { op: string; items?: Item[] };
export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

export type StepResult = { premium: number };
export type ScenarioResult = { results: StepResult[] };

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map((step) => {
    const items = step.items ?? [];
    const basePremium = items.length === 0 ? 0 : 110;
    return { premium: basePremium + PROCESSING_FEE };
  });
  return { results };
};

