export type Item = { type: string };
export type Step = { op: string; items?: Item[] };
export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

export type StepResult = { premium: number };
export type ScenarioResult = { results: StepResult[] };

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const PROCESSING_FEE = 5;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const basePremiumForType = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)]
    .map(([type, count]) => basePremiumForType(type, count))
    .reduce((total, premium) => total + premium, 0);

const quotePremium = (items: Item[] = []): number => {
  const policyBase = policyBasePremium(items);
  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items),
  })),
});

