export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};
export type Step = { op: string; items?: Item[] };
export type Customer = { yearsWithMHPCO: number };
export type Scenario = { customer: Customer; steps: Step[] };

export type StepResult = { premium: number };
export type ScenarioResult = { results: StepResult[] };

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const PROCESSING_FEE = 5;

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const LOYALTY_THRESHOLD_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const basePremiumForType = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)]
    .map(([type, count]) => basePremiumForType(type, count))
    .reduce((total, premium) => total + premium, 0);

const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const curseSurcharge = (item: Item): number =>
  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;

const highEnchantmentSurcharge = (item: Item): number =>
  isHighlyEnchanted(item)
    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0;

