  return Math.ceil(
    policyBase +
      itemModifierSurcharges(items) +
      policyModifiers +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(scenario.customer, step.items),
