const BASE={sword:100,amulet:60,staff:80,potion:40,rune:25,moonstone:25};
const types=Object.keys(BASE);
// policy of up to 2 items (counts 1..2 of one type, or two different types)
const policies=[];
for(const t of types){for(let n=1;n<=4;n++)policies.push(Array(n).fill(t));}
for(const a of types)for(const b of types)policies.push([a,b]);
const baseOf=(items)=>{const c={};items.forEach(t=>c[t]=(c[t]||0)+1);
  return Object.entries(c).reduce((s,[t,n])=>s+(n===3?60:n*BASE[t]),0);};
for(const p of policies)for(const loyal of [0,1])for(const follow of [0,1]){
