type Policy = { items: Item[]; remainingCap: number };

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const damagePayout = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
  const payout = Math.floor(
    incident.damages.reduce((total, damage) => total + damagePayout(damage), 0),
  );
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies = new Map<number, Policy>();
  let quotesSoFar = 0;

  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy ?? -1)!;
      return settleClaim(policy, step.incident!);
    }

    const items = step.items ?? [];
    const isFollowUpContract = quotesSoFar > 0;
    quotesSoFar += 1;
    policies.set(index, {
      items,
      remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
    });
    return {
      premium: quotePremium(scenario.customer, items, isFollowUpContract),
    };
  });

  return { results };
};

