// Policy-wide modifiers are rates applied to the policy base premium.
// Surcharges are positive, discounts negative; they sum to one net rate.
const policyModifierRates = (
  customer: Customer,
  isFollowUpContract: boolean,
): number[] => [
  FIRST_INSURANCE_SURCHARGE_RATE,
  isLoyalCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0,
  isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0,
];

const netPolicyModifierRate = (
  customer: Customer,
  isFollowUpContract: boolean,
): number =>
  policyModifierRates(customer, isFollowUpContract).reduce(
    (total, rate) => total + rate,
    0,
  );

const quotePremium = (
  customer: Customer,
  items: Item[] = [],
  isFollowUpContract = false,
): number => {
  const policyBase = policyBasePremium(items);
  const policyModifiers =
    policyBase * netPolicyModifierRate(customer, isFollowUpContract);
  return Math.ceil(
    policyBase +
      itemModifierSurcharges(items) +
      policyModifiers +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  // Counts every step, not only quote steps. Indistinguishable from counting
  // quotes while every step is a quote; the claim tests will force the split.
  let stepsSoFar = 0;
  const results = scenario.steps.map((step) => {
    const isFollowUpContract = stepsSoFar > 0;
    stepsSoFar += 1;
    return {
      premium: quotePremium(scenario.customer, step.items, isFollowUpContract),
    };
  });
  return { results };
};

